using UnityEngine;using UnityEditor;using UnityEditor.IMGUI.Controls;
[CustomEditor(typeof(TrainingMotionAction))]
public sealed class TrainingMotionActionEditor:Editor {
 TrainingMotionAction draft;SerializedObject data;int frame,hurtIndex;bool mirror;string status="Draft only. Save explicitly.";GameObject preview;SpriteRenderer renderer;BoxBoundsHandle box=new BoxBoundsHandle();
 public bool ScenePreviewEnabled=>preview!=null;
 void OnEnable(){Reload();SceneView.duringSceneGui+=SceneGUI;EditorApplication.playModeStateChanged+=PlayChanged;Undo.undoRedoPerformed+=RefreshPreview;}
 void OnDisable(){SceneView.duringSceneGui-=SceneGUI;EditorApplication.playModeStateChanged-=PlayChanged;Undo.undoRedoPerformed-=RefreshPreview;StopScenePreview();if(draft!=null)DestroyImmediate(draft);}
 void PlayChanged(PlayModeStateChange state){if(state==PlayModeStateChange.ExitingEditMode)StopScenePreview();}
 void Reload(){if(draft!=null)DestroyImmediate(draft);draft=Instantiate((TrainingMotionAction)target);draft.hideFlags=HideFlags.HideAndDontSave & ~HideFlags.NotEditable;draft.name=target.name;data=new SerializedObject(draft);RefreshPreview();}
 public override void OnInspectorGUI(){if(Application.isPlaying){EditorGUILayout.HelpBox("Author outside Play. Runtime never saves this asset.",MessageType.Info);return;}if(draft==null)Reload();data.Update();EditorGUILayout.LabelField("Forward X / up Y, meters. No movement performance.");EditorGUILayout.PropertyField(data.FindProperty("playback"));if(draft.playback==TrainingMotionPlayback.FrameHolds)EditorGUILayout.PropertyField(data.FindProperty("loop"));else EditorGUILayout.HelpBox("Game-phase playback preserves existing transitions; holdFrames/loop are ignored. Jump preview uses nominal half airtime; runtime uses vertical velocity.",MessageType.Info);EditorGUILayout.PropertyField(data.FindProperty("poses"),true);data.ApplyModifiedProperties();frame=Mathf.Max(0,EditorGUILayout.IntField("Preview frame (60Hz)",frame));mirror=EditorGUILayout.Toggle("Mirror left",mirror);hurtIndex=Mathf.Max(0,EditorGUILayout.IntField("Scene hurt index",hurtIndex));EditorGUILayout.HelpBox("Hurt part IDs refer to Hurtboxes.asset; priority/defense remain there. Missing parts fall back. Keep IDs unchanged.",MessageType.Info);Preview();EditorGUILayout.BeginHorizontal();if(GUILayout.Button("Open Scene visual editing")){OpenScenePreview();SceneView.lastActiveSceneView?.Frame(new Bounds(new Vector3(0,.9f,0),new Vector3(2.4f,2.4f,.1f)),false);}if(GUILayout.Button("Close Scene preview"))StopScenePreview();EditorGUILayout.EndHorizontal();EditorGUILayout.BeginHorizontal();if(GUILayout.Button("Save same asset")){if(!draft.Validate(out var error))status=error;else{SaveDraft((TrainingMotionAction)target,draft);status="Saved same authoritative asset";}}if(GUILayout.Button("Cancel / reload")){Reload();status="Unsaved draft discarded";}EditorGUILayout.EndHorizontal();EditorGUILayout.HelpBox(status+"\nScene: cyan position handle = image offset; green box = selected hurt index. All edits are draft until Save.",MessageType.Info);RefreshPreview();}
 public static void SaveDraft(TrainingMotionAction target,TrainingMotionAction draft){if(Application.isPlaying)throw new System.InvalidOperationException("No authoring save during Play");if(!draft.Validate(out var error))throw new System.ArgumentException(error);var name=target.name;Undo.RecordObject(target,"Save motion action draft");EditorUtility.CopySerialized(draft,target);target.name=name;EditorUtility.SetDirty(target);AssetDatabase.SaveAssetIfDirty(target);}
 float VisualScale(){foreach(var guid in AssetDatabase.FindAssets("t:TrainingApprovedCharacter")){var c=AssetDatabase.LoadAssetAtPath<TrainingApprovedCharacter>(AssetDatabase.GUIDToAssetPath(guid));if(c!=null&&c.OwnsMotion((TrainingMotionAction)target)&&c.bodyCalibration!=null)return c.bodyCalibration.VisualScale;}return 1;}
 public void OpenScenePreview(){if(Application.isPlaying||draft==null)return;if(preview==null){preview=new GameObject("Motion action preview (draft, no combat)");preview.hideFlags=HideFlags.HideAndDontSave;renderer=preview.AddComponent<SpriteRenderer>();renderer.sortingOrder=30000;}RefreshPreview();}
 public void StopScenePreview(){if(preview!=null)DestroyImmediate(preview);preview=null;renderer=null;SceneView.RepaintAll();}
 void RefreshPreview(){if(renderer==null||draft==null)return;var pose=PreviewPose();renderer.enabled=pose!=null;if(pose==null)return;renderer.sprite=pose.sprite;renderer.flipX=mirror;renderer.transform.position=new Vector3(pose.visualOffset.x*(mirror?-1:1),pose.visualOffset.y,-.01f);renderer.transform.localScale=Vector3.one*VisualScale();SceneView.RepaintAll();}
 void SceneGUI(SceneView scene){if(preview==null||Application.isPlaying||draft==null)return;var pose=PreviewPose();if(pose==null)return;int facing=mirror?-1:1;Handles.color=Color.cyan;Handles.Label(new Vector3(0,2.2f,0),target.name+" DRAFT - Save in Inspector; no simulation");EditorGUI.BeginChangeCheck();var image=Handles.PositionHandle(new Vector3(pose.visualOffset.x*facing,pose.visualOffset.y,0),Quaternion.identity);if(EditorGUI.EndChangeCheck()){Undo.RecordObject(draft,"Drag motion sprite draft");pose.visualOffset=new Vector2(image.x*facing,image.y);RefreshPreview();Repaint();}Handles.color=Color.gray;Handles.DrawLine(Vector3.left*2,Vector3.right*2);if(pose.hurt.Length==0)return;var h=pose.hurt[Mathf.Clamp(hurtIndex,0,pose.hurt.Length-1)];using(new Handles.DrawingScope(Matrix4x4.Scale(new Vector3(facing,1,1)))){box.axes=PrimitiveBoundsHandle.Axes.X|PrimitiveBoundsHandle.Axes.Y;box.center=h.center;box.size=new Vector3(h.size.x,h.size.y,.01f);box.SetColor(Color.green);EditorGUI.BeginChangeCheck();box.DrawHandle();if(EditorGUI.EndChangeCheck()){Undo.RecordObject(draft,"Drag motion hurt draft");h.inheritBodyShape=false;h.center=(Vector2)box.center;h.size=new Vector2(Mathf.Max(.001f,box.size.x),Mathf.Max(.001f,box.size.y));Repaint();}}}
 TrainingMotionPose PreviewPose(){if(draft==null)return null;if(draft.playback!=TrainingMotionPlayback.FrameHolds){var profile=AssetDatabase.LoadAssetAtPath<ApprovedLocomotionProfile>(MotionProfileAdoption.ProfilePath);if(profile!=null&&profile.TryRead(out var settings,out _)){if(draft.playback==TrainingMotionPlayback.BackstepPhases&&draft.poses.Length==9)return draft.poses[ArmoredStaticPoseView.BackstepSequenceIndex(frame/60f,settings.pose1EndFrame,settings.pose2EndFrame)];if(draft.playback==TrainingMotionPlayback.JumpPhases&&draft.poses.Length>=2)return draft.poses[frame<settings.jumpAirFrames*.5f?0:1];}}return draft.Sample(frame);}
 void Preview(){var pose=PreviewPose();if(pose==null)return;var r=GUILayoutUtility.GetRect(100,250,GUILayout.ExpandWidth(true));EditorGUI.DrawRect(r,new Color(.06f,.08f,.1f));float scale=100;var foot=new Vector2(r.center.x,r.yMax-8);var sprite=pose.sprite;float pixels=scale*VisualScale()/sprite.pixelsPerUnit;var size=sprite.rect.size*pixels;var anchor=foot+new Vector2(pose.visualOffset.x,-pose.visualOffset.y)*scale;var draw=new Rect(anchor.x-sprite.pivot.x*pixels,anchor.y-(sprite.rect.height-sprite.pivot.y)*pixels,size.x,size.y);GUI.BeginClip(r);var previous=GUI.matrix;if(mirror)GUI.matrix=Matrix4x4.TRS(new Vector3(r.width,0,0),Quaternion.identity,new Vector3(-1,1,1))*previous;draw.position-=r.position;GUI.DrawTextureWithTexCoords(draw,sprite.texture,new Rect(sprite.rect.x/sprite.texture.width,sprite.rect.y/sprite.texture.height,sprite.rect.width/sprite.texture.width,sprite.rect.height/sprite.texture.height),true);GUI.matrix=previous;GUI.EndClip();Handles.BeginGUI();Handles.color=Color.gray;Handles.DrawLine(new Vector2(r.x,foot.y),new Vector2(r.xMax,foot.y));foreach(var h in pose.hurt){Handles.color=Color.green;Handles.DrawWireCube(foot+new Vector2(h.center.x*(mirror?-1:1),-h.center.y)*scale,h.size*scale);}Handles.EndGUI();}
}
